from decimal import Decimal

def run(payload):
    subtotal = Decimal(str(payload.get("subtotal", "0")))
    fixed = Decimal(str(payload.get("fixed", "0")))
    rate = Decimal(str(payload.get("rate", "0")))

    if fixed:
        total = subtotal - fixed
    else:
        total = subtotal * (1 - rate)

    total = total.quantize(Decimal('0.01'), rounding=Decimal('0.005'))
    return {"total": total}
